function nearestTripleSum(nums: number[], target: number): number {
  const a = [...nums].sort((x, y) => x - y);
  const n = a.length;
  let best = a[0] + a[1] + a[2];
  for (let i = 0; i < n - 2; i++) {
    let lo = i + 1, hi = n - 1;
    while (lo < hi) {
      const s = a[i] + a[lo] + a[hi];
      const d = Math.abs(s - target), bd = Math.abs(best - target);
      if (d < bd || (d === bd && s < best)) best = s;
      if (s === target) return s;
      if (s < target) lo++;
      else hi--;
    }
  }
  return best;
}

